    def pos(v, default=None):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def is_pos(v):
        return isinstance(v, (list, tuple)) and len(v) >= 2 and isinstance(v[0], (int, float)) and isinstance(v[1], (int, float))

    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0
    sx, sy = pos(observation.get("self_position", (0, 0)), (0, 0))
    ox, oy = pos(observation.get("opponent_position", (sx, sy)), (sx, sy))

    obstacles = set()
    for k in ("obstacles", "walls", "blocked_cells"):
        for a in observation.get(k, []):
            q = pos(a)
            if q is not None:
                obstacles.add(q)

    targets = []
    for k in ("resources", "resource_positions", "targets", "control_points", "capture_points", "objectives", "neutral_points"):
