            for a in observation.get(k, []):
                q = pos(a)
                if q is not None:
                    targets.append(q)

    moves = [(0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)]

    def valid(nx, ny):
        return (w <= 0 or (0 <= nx < w)) and (h <= 0 or (0 <= ny < h)) and (nx, ny) not in obstacles

    def dist(ax, ay, bx, by):
        return abs(ax - bx) + abs(ay - by)

    nearest_target = None
    best_td = 10**9
    for tx, ty in targets:
        d = dist(sx, sy, tx, ty)
        if d < best_td or (d == best_td and (tx, ty) < nearest_target):
            best_td = d
            nearest_target = (tx, ty)

