            if (dx, dy) == (0, 0):
                score -= 1
        else:
            score += 0

        nd = dist(nx, ny, ox, oy)
        if threatened:
            score += nd * 5
        else:
            score += nd

        if (nx, ny) in obstacles:
            score -= 1000

        if nearest_target is not None and (nx, ny) == nearest_target:
            score += 25

        if w > 0 and h > 0:
            edge = min(nx, ny, w - 1 - nx, h - 1 - ny)
            score += edge

        if best_score is None or score > best_score or (score == best_score and (dx, dy) < best_move):
            best_score = score
            best_move = (dx, dy)

    return [best_move[0], best_move[1]]

